    let mut score = 0.0;

    // Penalty for creating a new bin
    if fitting_bins_count == 0 {
        score += 18.0;
    }

    // Reward for filling the bin to capacity or close to it
    if post_residual <= 5 {
        score -= 4.0 * (bin_capacity - post_residual) as f64;
    } else if post_residual <= 20 {
        score -= 2.0 * (bin_capacity - post_residual) as f64;
    }

    // Penalty for low mean residual
    if mean_residual < bin_capacity / 4.0 {
        score += 3.0 * (bin_capacity / 4.0 - mean_residual);
    }

    // Reward for small item size relative to bin capacity
    if item_size <= bin_capacity / 5.0 {
        score -= 0.9;
    }

    // Penalize for large lookahead item that cannot fit in the current bin
    if next_item_size > post_residual {
        score += 6.0 * (next_item_size - post_residual) as f64;
    }

    // Reward for fitting items in existing bins over opening new ones
    if fitting_bins_count > 0 {
        score -= 0.75;
    }

    // Penalize for high open bin count
    if open_bins_count > total_items / 12 {
        score += 2.0 * (open_bins_count - total_items / 12) as f64;
    }

    score
}

