pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Penalize creating bins that are too close to being full
    if bin_capacity - bin_residual < 50 {
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Reward using bins with more capacity left
    score -= post_residual as f64 / bin_capacity as f64;

    // Penalize creating too many open bins
    if open_bins_count > mean_residual as usize {
        score += (open_bins_count - mean_residual) as f64 * 0.5;
    }

    // Reward using fitting bins first
    if fitting_bins_count > 1 {
        score -= (fitting_bins_count - 1) as f64 * 0.2;
    }

    // Penalize creating unusable dead space
    if post_residual < item_size / 2 {
        score += post_residual as f64 * 0.3;
    }

    // Reward for lookahead compatibility
    if next_item_size > 0 && bin_capacity - bin_residual >= next_item_size {
        score -= (bin_capacity - bin_residual - next_item_size) as f64 * 0.1;
    }

    score
}

